/* crosswalk cards, r14. */
(window.LADDER_CARDS=window.LADDER_CARDS||{})["14a"]=[{"q":"f(x) = x³ − 3x. f′(x) = 3x² − 3 is 0 at −1 and 1. What are −1 and 1 called?","a":"critical points of f","w":["tops of f","zeros of f","inflection points of f"],"why":"A critical point has slope 0 or none; which are tops is another question."},
 {"q":"f(x) = |x − 2| at 2: no slope there. Is 2 a critical point?","a":"yes: a critical point with no slope","w":["no: the slope is not 0","yes: its slope there is 0","no: f is not continuous at 2"],"why":"A critical point has a slope of 0 or no slope at all."},
 {"q":"x³ at 0: slope 0. Is 0 a top or a bottom?","a":"neither: x³ is below 0 on the left and above on the right","w":["a bottom","a top","both"],"why":"Flat-top runs from a top to slope 0, not back."},
 {"q":"Greatest value of x³ − 12x on [−3, 5]: the list is f(−3), f(−2), f(2), f(5). What is this list?","a":"the candidates: both ends and the critical points inside","w":["the critical values only","the tops of f","the zeros of the slope"],"why":"Candidates: the greatest value is at an end or a critical point inside."},
 {"q":"x⁴ − 8x² on [−1, 3]: critical values 0 and −16, f(3) = 9. What is the greatest value?","a":"9, at the end 3","w":["0, at the critical point 0","−16, at 2","none on a closed interval"],"why":"The ends are candidates too."},
 {"q":"p(x) = x³ − 3x + 1 has a top at −1 with value 3, and p(3) = 19. What is 3 to p?","a":"a local maximum value, not the greatest","w":["the global maximum","a critical point","a bottom value"],"why":"A top is greatest only among its neighbours."},
 {"q":"f on [0, 4] is greatest at the end 4. Is 4 a local maximum, on this page?","a":"no: no neighbourhood of 4 lies in [0, 4]","w":["yes: f is greatest there","yes: every greatest value is one","no: f′(4) is not 0"],"why":"The ladder does not let an end be a top, since flat-top fails there."},
 {"q":"f has a top at c and a slope at c. What is f′(c)?","a":"0, by flat-top","w":["negative","positive","it may be any number"],"why":"Chord slopes are at most 0 on the right and at least 0 on the left."},
 {"q":"Polynomial f, not constant, on a closed interval. Why does the candidates test finish?","a":"its slope has finitely many zeros","w":["it has no critical points","its ends are its only candidates","its greatest value is at a top"],"why":"The slope is a polynomial with at most finitely many zeros."},
 {"q":"x on [0, 1]: no critical point inside. Does it have a greatest value?","a":"yes: 1, at the end 1","w":["no: no critical point","yes: at the middle","no: slope 1 everywhere"],"why":"An end can give the greatest value."},
 {"q":"f has a high point at c inside the interval and a slope at c. Then f′(c) = 0. What is it called?","a":"the flat-top technique","w":["the averaging step","the tangent step","the d-mark"],"why":"The page names it the flat-top technique, and gives the accepted name in brackets: Fermat's."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["14b"]=[{"q":"x² − 6x + 5 on [1, 5]: f(1) = f(5) = 0, a polynomial. What does level-ends promise?","a":"some c in (1, 5) with f′(c) = 0","w":["c = 3 and only 3","f has a top inside","some c with f(c) = 0"],"why":"It promises some c strictly inside; here it is 3."},
 {"q":"|x| on [−1, 1]: equal ends, and no slope inside is 0. Which hypothesis fails?","a":"a slope at every input inside","w":["continuity on [−1, 1]","equal ends","the interval is closed"],"why":"|x| has no slope at 0."},
 {"q":"1/x² on [−1, 1]: equal ends, slope never 0. Which hypothesis fails?","a":"continuity: 1/x² has no value at 0","w":["a slope inside","equal ends","nothing fails"],"why":"Level-ends needs f continuous on the closed interval."},
 {"q":"x² on [−1, 2] has slope 0 at 0, yet f(−1) = 1 and f(2) = 4. Does it break level-ends?","a":"no: level-ends runs one way only","w":["yes: the ends should match","yes: c should be the middle","no: x² is not continuous"],"why":"A slope of 0 inside does not give equal ends."},
 {"q":"x³ + 2x − 5 has slope 3x² + 2, never 0. How many zeros can it have?","a":"at most one","w":["at most two","exactly three","none"],"why":"Two zeros would put a zero of the slope between them."},
 {"q":"x⁴ − 5x² + 4 has zeros −2, −1, 1, 2. Where must its slope be 0?","a":"once strictly between each neighbouring pair","w":["at the four zeros","only at 0","nowhere"],"why":"Zeros-of-slopes: level-ends on each stretch."},
 {"q":"x³ − x on [−1, 1]: c = ±1/√3. What does this show about level-ends’s c?","a":"there may be more than one","w":["it is always the middle","there is exactly one","it is an end"],"why":"Level-ends promises some c, not exactly one."},
 {"q":"Does the proof of level-ends say where c is?","a":"no: highest-and-lowest names no input","w":["yes: at the middle","yes: where f is greatest","yes: at an end"],"why":"It proves c exists and stops."},
 {"q":"A van leaves and returns to the same place, with a velocity at every instant. What does level-ends give?","a":"an instant with velocity 0","w":["an instant with speed at its greatest","a constant velocity","nothing: it may never stop"],"why":"Position has equal values at the two ends of the trip."},
 {"q":"f is continuous on [a, b], has a slope inside, and f(a) = f(b). Then f′(c) = 0 for some c between. What is it called?","a":"the level-ends technique","w":["the flat-top technique","the averaging step","the tangent step"],"why":"The page names it the level-ends technique, and gives the accepted name in brackets: Rolle's."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["14c"]=[{"q":"f(x) = x² on [1, 3]. f′(c) = (9 − 1)/(3 − 1) = 4 gives c = 2. What technique is running?","a":"average-slope","w":["level-ends","slope-bound","flat-top"],"why":"Some slope inside equals the chord’s slope; its accepted name is the mean value theorem."},
 {"q":"f continuous on [1, 5], a slope inside, f(1) = 3, f′ ≤ 2. What bound on f(5)?","a":"f(5) ≤ 11","w":["f(5) ≤ 8","f(5) = 11","f(5) ≥ 11"],"why":"Average-slope: f(5) − f(1) = 4f′(c) ≤ 8."},
 {"q":"x³ on [0, 2]: is c the middle, 1?","a":"no: c = 2/√3","w":["yes: always the middle","yes: for every polynomial","no: there is no c"],"why":"3c² = 4, so c = 2/√3; the middle is true for x², not in general."},
 {"q":"|x| on [−1, 2]: chord slope ⅓, slopes only ±1. Which hypothesis fails?","a":"a slope at every input inside","w":["continuity on [−1, 2]","equal ends","a bound on the slope"],"why":"|x| has no slope at 0."},
 {"q":"h(x) = f(x) − f(α) − m(x − α), with m the chord’s slope. What is h?","a":"the helper: f with the chord taken away","w":["the linearization at α","an antiderivative of f","the tangent line at α"],"why":"It is 0 at both ends, so level-ends applies to it."},
 {"q":"x³ on [−1, 1]: chord y = x, and c = 1/√3. Is the chord the tangent line at c?","a":"no: same slope, different lines","w":["yes: they share a slope","yes: by average-slope","no: the slopes differ"],"why":"The tangent at 1/√3 does not pass through 0."},
 {"q":"|f′| ≤ K inside [α, β], f continuous there. What does slope-bound give?","a":"|f(y) − f(x)| ≤ K|y − x|","w":["|f(x)| ≤ K","f′(c) = K for some c","f(β) − f(α) = K(β − α)"],"why":"Average-slope on [x, y], then the bound on f′(c)."},
 {"q":"A truck covers 48 km in 30 minutes, with a velocity at every instant. What follows?","a":"at some instant its speed is exactly 96 km/h","w":["its speed was 96 km/h throughout","it never passed 96 km/h","nothing about any instant"],"why":"Average velocity is the chord’s slope."},
 {"q":"f(b) − f(a) = f′(a)(b − a). Is this average-slope?","a":"no: it is the linearization, with an error","w":["yes, exactly","yes, with c = a","no: it is level-ends"],"why":"Average-slope puts the slope at some c, not at a."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["14d"]=[{"q":"f(x) = x³ − 12x, f′(x) = 3(x − 2)(x + 2). On which interval is f decreasing?","a":"[−2, 2]","w":["(−∞, −2]","[2, ∞)","all of ℝ"],"why":"Slope-sign-order: the slope is negative inside (−2, 2), ends included."},
 {"q":"f′(x) > 0 on (0, ∞), f continuous there. What does slope-sign-order give?","a":"f is increasing on (0, ∞)","w":["f has no top","f′ is increasing","f bends up"],"why":"Positive slopes inside an interval give increasing."},
 {"q":"1/x has slope −1/x² < 0 at every input. Is it decreasing on its whole domain?","a":"no: −1 < 1 and 1/(−1) < 1/1","w":["yes: every slope is negative","yes: by slope-sign-order","no: it has no slope at 1"],"why":"The domain is two intervals, not one."},
 {"q":"f′ = 0 at every input of (−2, 5) and f(1) = 4. What is f(3)?","a":"4","w":["0","not fixed by the facts","7"],"why":"Zero-slope-is-constant on an interval."},
 {"q":"x³ is increasing on ℝ. Is its slope positive at every input?","a":"no: at 0 it is 0","w":["yes: increasing means positive","yes, except at no input","no: it is negative at 0"],"why":"Slope-sign-order does not run backward."},
 {"q":"x³ + 3x² + 3x: slope 3(x + 1)², 0 only at −1. Increasing on ℝ?","a":"yes, by positive-but-finitely","w":["no: the slope is 0 at −1","yes, by zero-slope-is-constant","no: it has a top at −1"],"why":"Finitely many zeros of the slope do not stop the climb."},
 {"q":"0 left of 0 and 1 right of 0, with 0 left out: slope 0 everywhere. Is it constant?","a":"no: the domain is not an interval","w":["yes: zero-slope-is-constant","yes: its slope is 0","no: it has no slope"],"why":"Zero-slope-is-constant needs an interval."},
 {"q":"Every slope inside an interval is at least 0. What does x < y give?","a":"f(x) ≤ f(y)","w":["f(x) < f(y)","f(x) = f(y)","nothing"],"why":"Non-decreasing, by slope-sign-order."},
 {"q":"A puck has acceleration 0 on [0, 6] s. What does its velocity do?","a":"it stays the same","w":["it falls to 0","it grows steadily","nothing is fixed"],"why":"Zero-slope-is-constant, applied to the velocity."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["14e"]=[{"q":"Every antiderivative of 8x³ − 6x + 1 on ℝ. What is the family?","a":"2x⁴ − 3x² + x + C","w":["24x² − 6","2x⁴ − 3x² + x","8x⁴ − 6x² + x + C"],"why":"Run polynomial-slope backward term by term, then lift by + C."},
 {"q":"F′(x) = f(x) at every input of I. What is F?","a":"an antiderivative of f on I","w":["the slope of f","a linearization of f","the second slope of f"],"why":"The page’s definition; some books say primitive."},
 {"q":"F(x) = x³ + 2x + C, and F(1) = 4. What is C?","a":"1","w":["4","3","0"],"why":"1 + 2 + C = 4 fixes one member of the family."},
 {"q":"“The antiderivative of 2x is x².” What is missing?","a":"+ C: x² is one of them","w":["nothing","a factor 2","the term 2x"],"why":"All-antiderivatives: exactly the functions x² + C."},
 {"q":"f′ = g′ at every input of an interval. What does same-slopes give?","a":"f = g + C for one real C","w":["f = g","f − g is linear","f′ = 0"],"why":"f − g has slope 0, so is constant."},
 {"q":"Run the power technique backward on x⁻¹. What happens?","a":"it breaks: x⁰/0 names nothing","w":["it gives x⁻¹ again","it gives x⁰","it gives −x⁻²"],"why":"The technique needs n ≠ −1."},
 {"q":"A stone falls with acceleration −9.8 from rest at 67 m. Why is y(t) = 67 − 4.9t² the only height?","a":"all-antiderivatives twice, each constant fixed","w":["level-ends","the stone is falling","slope-sign-order"],"why":"y′(0) = 0 fixes one constant and y(0) = 67 the other."},
 {"q":"f″ = g″ on an interval. What is f − g?","a":"linear: mx + b","w":["a constant","0","anything"],"why":"Same-slopes twice."},
 {"q":"Two functions with slope 1/x² on ℝ without 0 differ by 1 on one side and 5 on the other. Does same-slopes fail?","a":"no: ℝ without 0 is two intervals","w":["yes: C must be one number","no: their slopes differ","yes: the slopes agree"],"why":"Same-slopes works on one interval at a time."}];
